n = int(input())

def isq(x):
    if x < 2:
        return x
    r = x
    y = (r + 1) // 2
    while y < r:
        r = y
        y = (r + x // r) // 2
    return r

def two(x):
    p = 2
    while p * p <= x:
        e = 0
        while x % p == 0:
            x //= p
            e += 1
        if p % 4 == 3 and e % 2 == 1:
            return False
        p += 1 if p == 2 else 2
    return not (x > 1 and x % 4 == 3)

